/* codeX starfield - fixed background only, no layout shift */
html, body {
  background: #000000 !important;
  background-color: #000000 !important;
}

#codex-starfield {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  max-width: 100vw !important;
  max-height: 100vh !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  z-index: 0 !important;
  pointer-events: none !important;
  display: block !important;
  background: radial-gradient(ellipse at center, #0a0a12 0%, #000000 70%) !important;
}

header,
.sticky,
nav,
[class*="header"] {
  z-index: 50 !important;
  position: relative;
}

