(function () {
  if (window.__CODEX_FX__) return;
  window.__CODEX_FX__ = true;

  var AUDIO_URL = "https://codex-theta-two.vercel.app/welcome-codex-v3.mp3";

  function initStars() {
    if (document.getElementById("codex-starfield")) return;

    var canvas = document.createElement("canvas");
    canvas.id = "codex-starfield";
    // Inline styles so it NEVER pushes page content down
    canvas.setAttribute(
      "style",
      [
        "position:fixed",
        "top:0",
        "left:0",
        "right:0",
        "bottom:0",
        "width:100vw",
        "height:100vh",
        "max-width:100vw",
        "max-height:100vh",
        "margin:0",
        "padding:0",
        "border:0",
        "z-index:0",
        "pointer-events:none",
        "display:block",
        "background:radial-gradient(ellipse at center,#0a0a12 0%,#000 70%)",
      ].join(";"),
    );

    // Append to body end (not prepend) so it can't create top gap
    document.body.appendChild(canvas);

    var ctx = canvas.getContext("2d");
    var stars = [];
    var mouse = { x: 0.5, y: 0.5 };
    var target = { x: 0.5, y: 0.5 };
    var COUNT = 160;

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    function makeStars() {
      stars = [];
      for (var i = 0; i < COUNT; i++) {
        stars.push({
          x: Math.random(),
          y: Math.random(),
          z: Math.random() * 0.8 + 0.2,
          r: Math.random() * 1.6 + 0.3,
          a: Math.random() * 0.6 + 0.35,
          tw: Math.random() * Math.PI * 2,
        });
      }
    }
    function draw() {
      mouse.x += (target.x - mouse.x) * 0.06;
      mouse.y += (target.y - mouse.y) * 0.06;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      var ox = (mouse.x - 0.5) * 50;
      var oy = (mouse.y - 0.5) * 50;
      for (var i = 0; i < stars.length; i++) {
        var s = stars[i];
        s.tw += 0.02 + s.z * 0.02;
        var twinkle = 0.55 + Math.sin(s.tw) * 0.45;
        var px = s.x * canvas.width + ox * s.z;
        var py = s.y * canvas.height + oy * s.z;
        ctx.beginPath();
        ctx.fillStyle = "rgba(255,255,255," + s.a * twinkle + ")";
        ctx.arc(px, py, s.r * s.z, 0, Math.PI * 2);
        ctx.fill();
      }
      requestAnimationFrame(draw);
    }
    window.addEventListener(
      "mousemove",
      function (e) {
        target.x = e.clientX / window.innerWidth;
        target.y = e.clientY / window.innerHeight;
      },
      { passive: true },
    );
    window.addEventListener(
      "touchmove",
      function (e) {
        if (!e.touches || !e.touches[0]) return;
        target.x = e.touches[0].clientX / window.innerWidth;
        target.y = e.touches[0].clientY / window.innerHeight;
      },
      { passive: true },
    );
    window.addEventListener("resize", resize);
    resize();
    makeStars();
    draw();
  }

  function showTapHint(onTap) {
    if (document.getElementById("codex-audio-unlock")) return;
    var btn = document.createElement("button");
    btn.id = "codex-audio-unlock";
    btn.type = "button";
    btn.textContent = "🔊 اضغط للترحيب";
    btn.setAttribute(
      "style",
      [
        "position:fixed",
        "left:16px",
        "bottom:16px",
        "z-index:99999",
        "border:1px solid rgba(255,255,255,.25)",
        "background:rgba(10,10,15,.92)",
        "color:#fff",
        "padding:10px 14px",
        "border-radius:12px",
        "font:600 13px/1.2 sans-serif",
        "cursor:pointer",
        "backdrop-filter:blur(10px)",
        "box-shadow:0 8px 30px rgba(0,0,0,.45)",
      ].join(";"),
    );
    btn.addEventListener("click", function () {
      onTap();
      btn.remove();
    });
    document.body.appendChild(btn);
    setTimeout(function () {
      if (btn.parentNode) btn.remove();
    }, 12000);
  }

  function playWelcome() {
    try {
      if (sessionStorage.getItem("codex_welcome_played") === "1") return;
      var audio = new Audio(AUDIO_URL);
      audio.preload = "auto";
      audio.volume = 1;
      var played = false;

      function go() {
        if (played) return;
        var p = audio.play();
        if (p && typeof p.then === "function") {
          p.then(function () {
            played = true;
            sessionStorage.setItem("codex_welcome_played", "1");
            var hint = document.getElementById("codex-audio-unlock");
            if (hint) hint.remove();
          }).catch(function () {
            showTapHint(go);
          });
        } else {
          played = true;
          sessionStorage.setItem("codex_welcome_played", "1");
        }
      }

      setTimeout(go, 500);
      ["pointerdown", "click", "touchstart", "keydown"].forEach(function (evt) {
        window.addEventListener(evt, go, { once: true, capture: true });
      });
    } catch (e) {}
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      initStars();
      playWelcome();
    });
  } else {
    initStars();
    playWelcome();
  }
})();
